+'use client';
+
+import { useEffect, useRef } from 'react';
+import Lenis from 'lenis';
+import { Loader } from '@/components/Loader';
+import { Nav } from '@/components/Nav';
+import { SectionIntro } from '@/components/SectionIntro';
+import { SectionMan } from '@/components/SectionMan';
+import { SectionWife } from '@/components/SectionWife';
+import { SectionLife } from '@/components/SectionLife';
+import { SectionWork } from '@/components/SectionWork';
+import { SectionAchievement } from '@/components/SectionAchievement';
+import { SectionGallery } from '@/components/SectionGallery';
+import { SectionFinal } from '@/components/SectionFinal';
+
+export default function CelebrationPage() {
+  const mainRef = useRef<HTMLElement>(null);
+
+  // Lenis smooth scroll
+  useEffect(() => {
+    const lenis = new Lenis({
+      duration: 1.3,
+      easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
+      touchMultiplier: 2,
+    });
+
+    let rafId: number;
+    const tick = (time: number) => {
+      lenis.raf(time * 1000);
+      rafId = requestAnimationFrame(tick);
+    };
+    rafId = requestAnimationFrame(tick);
+
+    return () => {
+      lenis.destroy();
+      cancelAnimationFrame(rafId);
+    };
+  }, []);
+
+  // Scroll reveal observer
+  useEffect(() => {
+    const reveals = document.querySelectorAll('.reveal');
+    if (!reveals.length) return;
+
+    const observer = new IntersectionObserver(
+      (entries) => {
+        entries.forEach((entry) => {
+          if (entry.isIntersecting) {
+            entry.target.classList.add('reveal--visible');
+            observer.unobserve(entry.target);
+          }
+        });
+      },
+      { threshold: 0.15, rootMargin: '0px 0px -60px 0px' }
+    );
+
+    reveals.forEach((el) => observer.observe(el));
+    return () => observer.disconnect();
+  }, []);
+
+  return (
+    <div className="celebration">
+      <Loader />
+      <Nav />
+      <main ref={mainRef}>
+        <SectionIntro />
+        <SectionMan />
+        <SectionWife />
+        <SectionLife />
+        <SectionWork />
+        <SectionAchievement />
+        <SectionGallery />
+        <SectionFinal />
+      </main>
+    </div>
+  );
+}

