+'use client';
+
+import { useEffect, useRef, useState } from 'react';
+
+type Phase = 'question' | 'camera' | 'reveal';
+
+export default function OneMoreThingPage() {
+  const [phase, setPhase] = useState<Phase>('question');
+  const [cameraError, setCameraError] = useState(false);
+  const [revealStep, setRevealStep] = useState(0);
+  const videoRef = useRef<HTMLVideoElement>(null);
+  const streamRef = useRef<MediaStream | null>(null);
+
+  const handleFindOut = async () => {
+    setPhase('camera');
+    try {
+      const stream = await navigator.mediaDevices.getUserMedia({
+        video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } },
+        audio: false,
+      });
+      streamRef.current = stream;
+      if (videoRef.current) {
+        videoRef.current.srcObject = stream;
+      }
+    } catch {
+      setCameraError(true);
+    }
+  };
+
+  useEffect(() => {
+    if (phase !== 'camera' || cameraError) return;
+
+    const timer = setTimeout(() => {
+      setRevealStep(1);
+    }, 2000);
+
+    return () => clearTimeout(timer);
+  }, [phase, cameraError]);
+
+  useEffect(() => {
+    if (revealStep === 0) return;
+
+    const delays = [2000, 2000, 2500, 3000];
+    const step = revealStep;
+
+    if (step <= delays.length) {
+      const timer = setTimeout(() => {
+        setRevealStep(step + 1);
+      }, delays[step - 1]);
+      return () => clearTimeout(timer);
+    }
+  }, [revealStep]);
+
+  useEffect(() => {
+    return () => {
+      streamRef.current?.getTracks().forEach((t) => t.stop());
+    };
+  }, []);
+
+  const closeModal = () => {
+    streamRef.current?.getTracks().forEach((t) => t.stop());
+    streamRef.current = null;
+    setPhase('reveal');
+  };
+
+  return (
+    <main className="omt">
+      <a href="/celebration" className="omt__back">
+        <span className="omt__back-arrow">←</span>
+        <span>Back</span>
+      </a>
+      {/* Phase 1: Question */}
+      <div className={`omt__question ${phase !== 'question' ? 'omt__question--hidden' : ''}`}>
+        <span className="omt__label">A question for Baba</span>
+        <h1 className="omt__heading">
+          Who gave his children a life<br />
+          they&apos;ll always be grateful for?
+        </h1>
+        <button className="omt__btn" onClick={handleFindOut}>
+          <span>Find out</span>
+        </button>
+      </div>
+
+      {/* Phase 2: Camera modal */}
+      {phase === 'camera' && (
+        <div className="omt__camera-overlay" onClick={closeModal}>
+          <div className="omt__camera-window" onClick={(e) => e.stopPropagation()}>
+            <div className="omt__camera-frame">
+              {!cameraError ? (
+                <video
+                  ref={videoRef}
+                  autoPlay
+                  playsInline
+                  muted
+                  className="omt__camera-feed"
+                />
+              ) : (
+                <div className="omt__camera-fallback">
+                  <p>The camera couldn&apos;t be opened.</p>
+                  <p>But the answer is still the same.</p>
+                </div>
+              )}
+
+              {/* Reveal messages inside the camera window */}
+              <div className={`omt__reveal ${revealStep >= 1 ? 'omt__reveal--visible' : ''}`}>
+                <p className="omt__reveal-text omt__reveal-text--main">
+                  You did, Baba.
+                </p>
+              </div>
+              {revealStep >= 2 && (
+                <p className="omt__reveal-text omt__reveal-text--sub">
+                  And if you ever wonder whether you did enough…
+                </p>
+              )}
+              {revealStep >= 3 && (
+                <p className="omt__reveal-text omt__reveal-text--sub">
+                  We hope you can see what we see.
+                </p>
+              )}
+              {revealStep >= 4 && (
+                <p className="omt__reveal-text omt__reveal-text--sub">
+                  You gave us more than you realize.
+                </p>
+              )}
+            </div>
+
+            <button className="omt__camera-close" onClick={closeModal} aria-label="Close">
+              ✕
+            </button>
+          </div>
+        </div>
+      )}
+
+      {/* Phase 3: Final message */}
+      {phase === 'reveal' && (
+        <div className="omt__final">
+          <h2 className="omt__final-heading">Happy Birthday, Baba.</h2>
+          <p className="omt__final-copy">
+            With love, always — Hasan, Faiyza & Danish.
+          </p>
+        </div>
+      )}
+    </main>
+  );
+}

