+'use client';
+
+import { useEffect, useRef, useState } from 'react';
+import { useRouter } from 'next/navigation';
+
+export default function CoverPage() {
+  const router = useRouter();
+  const canvasRef = useRef<HTMLCanvasElement>(null);
+  const [entered, setEntered] = useState(false);
+
+  // Canvas animation
+  useEffect(() => {
+    const canvas = canvasRef.current;
+    if (!canvas) return;
+    const ctx = canvas.getContext('2d');
+    if (!ctx) return;
+
+    const resize = () => {
+      const dpr = Math.min(window.devicePixelRatio, 2);
+      canvas.width = window.innerWidth * dpr;
+      canvas.height = window.innerHeight * dpr;
+      ctx.scale(dpr, dpr);
+      canvas.style.width = window.innerWidth + 'px';
+      canvas.style.height = window.innerHeight + 'px';
+    };
+    resize();
+    window.addEventListener('resize', resize);
+
+    let frame = 0;
+    let rafId: number;
+
+    const draw = () => {
+      const w = window.innerWidth;
+      const h = window.innerHeight;
+      frame += 0.3;
+
+      // Warm dark gradient
+      const grad = ctx.createLinearGradient(w * 0.2, 0, w * 0.8, h);
+      grad.addColorStop(0, '#151210');
+      grad.addColorStop(0.3, '#1D1915');
+      grad.addColorStop(0.6, '#231E19');
+      grad.addColorStop(1, '#12100E');
+      ctx.fillStyle = grad;
+      ctx.fillRect(0, 0, w, h);
+
+      // Subtle warm light that drifts
+      const lightX = w * (0.4 + 0.15 * Math.sin(frame * 0.008));
+      const lightY = h * (0.35 + 0.1 * Math.cos(frame * 0.006));
+      const lightGrad = ctx.createRadialGradient(lightX, lightY, 0, lightX, lightY, w * 0.5);
+      lightGrad.addColorStop(0, 'rgba(196,168,130,0.06)');
+      lightGrad.addColorStop(1, 'transparent');
+      ctx.fillStyle = lightGrad;
+      ctx.fillRect(0, 0, w, h);
+
+      // Film grain
+      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
+      const data = imageData.data;
+      for (let i = 0; i < data.length; i += 20) {
+        const noise = (Math.random() - 0.5) * 6;
+        data[i] = Math.max(0, Math.min(255, data[i] + noise));
+        data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
+        data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
+      }
+      ctx.putImageData(imageData, 0, 0);
+
+      rafId = requestAnimationFrame(draw);
+    };
+
+    rafId = requestAnimationFrame(draw);
+
+    return () => {
+      window.removeEventListener('resize', resize);
+      cancelAnimationFrame(rafId);
+    };
+  }, []);
+
+  // Entrance animations
+  useEffect(() => {
+    const timers: NodeJS.Timeout[] = [];
+
+    const animate = (selector: string, delay: number) => {
+      const el = document.querySelector(selector);
+      if (!el) return;
+      timers.push(setTimeout(() => {
+        (el as HTMLElement).style.opacity = '1';
+        (el as HTMLElement).style.transform = 'translateY(0)';
+      }, delay));
+    };
+
+    animate('.cover__eyebrow', 600);
+    animate('.cover__name', 900);
+    animate('.cover__subtitle', 1200);
+    animate('.cover__enter', 1600);
+    animate('.cover__scroll-hint', 2000);
+    animate('.cover__scroll-line', 2000);
+
+    return () => timers.forEach(clearTimeout);
+  }, []);
+
+  const handleEnter = () => {
+    setEntered(true);
+    document.body.style.background = 'var(--color-espresso)';
+    setTimeout(() => {
+      router.push('/celebration');
+    }, 800);
+  };
+
+  return (
+    <main
+      className="cover"
+      style={{
+        opacity: entered ? 0 : 1,
+        transition: 'opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1)',
+      }}
+    >
+      <div className="cover__canvas-wrap">
+        <canvas ref={canvasRef} className="cover__canvas" />
+      </div>
+      <img
+        src="/images/image1.png"
+        alt=""
+        className="cover__image"
+      />
+      <div className="cover__vignette" />
+      <div className="cover__gradient" />
+
+      <div className="cover__content">
+        <span className="cover__eyebrow">A celebration of</span>
+        <h1 className="cover__name">Faiyaz</h1>
+        <p className="cover__subtitle">A father. A husband. A champion.</p>
+        <div className="cover__enter">
+          <button className="cover__enter-btn" onClick={handleEnter}>
+            <span>Enter</span>
+          </button>
+        </div>
+      </div>
+
+      <span className="cover__scroll-hint">Scroll</span>
+      <div className="cover__scroll-line" />
+    </main>
+  );
+}

