+'use client';
+
+import { useEffect, useRef } from 'react';
+
+export function Cursor() {
+  const ref = useRef<HTMLDivElement>(null);
+
+  useEffect(() => {
+    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) return;
+    const el = ref.current;
+    if (!el) return;
+
+    let mx = 0, my = 0, cx = 0, cy = 0;
+
+    const move = (e: MouseEvent) => { mx = e.clientX; my = e.clientY; };
+    const enter = () => el.classList.add('cursor--visible');
+    const leave = () => el.classList.remove('cursor--visible');
+
+    const hoverTargets = 'a, button, .hoverable, .nav__link, .cover__enter-btn, .section-gift__trigger';
+    const addHover = () => el.classList.add('cursor--hover');
+    const removeHover = () => el.classList.remove('cursor--hover');
+
+    const animate = () => {
+      cx += (mx - cx) * 0.12;
+      cy += (my - cy) * 0.12;
+      el.style.left = cx + 'px';
+      el.style.top = cy + 'px';
+      requestAnimationFrame(animate);
+    };
+
+    document.addEventListener('mousemove', move);
+    document.addEventListener('mouseenter', enter);
+    document.addEventListener('mouseleave', leave);
+
+    let links = document.querySelectorAll(hoverTargets);
+    links.forEach((l) => {
+      l.addEventListener('mouseenter', addHover);
+      l.addEventListener('mouseleave', removeHover);
+    });
+
+    const raf = requestAnimationFrame(animate);
+
+    // Re-query after mount for dynamic elements
+    const timer = setTimeout(() => {
+      links = document.querySelectorAll(hoverTargets);
+      links.forEach((l) => {
+        l.addEventListener('mouseenter', addHover);
+        l.addEventListener('mouseleave', removeHover);
+      });
+    }, 1000);
+
+    return () => {
+      document.removeEventListener('mousemove', move);
+      document.removeEventListener('mouseenter', enter);
+      document.removeEventListener('mouseleave', leave);
+      links.forEach((l) => {
+        l.removeEventListener('mouseenter', addHover);
+        l.removeEventListener('mouseleave', removeHover);
+      });
+      cancelAnimationFrame(raf);
+      clearTimeout(timer);
+    };
+  }, []);
+
+  return <div ref={ref} className="cursor" aria-hidden="true" />;
+}

