+'use client';
+
+import { useEffect, useState } from 'react';
+
+export function Loader() {
+  const [progress, setProgress] = useState(0);
+  const [done, setDone] = useState(false);
+
+  useEffect(() => {
+    let frame = 0;
+    const total = 80;
+    let rafId: number;
+
+    const tick = () => {
+      frame++;
+      setProgress(Math.min(Math.round((frame / total) * 100), 100));
+      if (frame < total) {
+        rafId = requestAnimationFrame(tick);
+      } else {
+        setTimeout(() => setDone(true), 300);
+      }
+    };
+
+    // Animate entrance
+    const textEl = document.querySelector('.loader__text');
+    const barEl = document.querySelector('.loader__bar-fill');
+    if (textEl) {
+      (textEl as HTMLElement).style.opacity = '1';
+      (textEl as HTMLElement).style.transform = 'translateY(0)';
+    }
+    if (barEl) {
+      (barEl as HTMLElement).style.transition = 'transform 2s cubic-bezier(0.16, 1, 0.3, 1)';
+      requestAnimationFrame(() => {
+        (barEl as HTMLElement).style.transform = 'scaleX(1)';
+      });
+    }
+
+    rafId = requestAnimationFrame(tick);
+    return () => cancelAnimationFrame(rafId);
+  }, []);
+
+  return (
+    <div className={`loader ${done ? 'loader--done' : ''}`}>
+      <div className="loader__text">For Baba</div>
+      <div className="loader__bar">
+        <div className="loader__bar-fill" />
+      </div>
+    </div>
+  );
+}

