+'use client';
+
+import { useEffect, useState } from 'react';
+
+const sectionLinks = [
+  { label: 'Introduction', href: '#top' },
+  { label: 'The Man', href: '#man' },
+  { label: 'Partnership', href: '#wife' },
+  { label: 'Life They Built', href: '#life' },
+  { label: 'Work', href: '#work' },
+  { label: 'Achievement', href: '#achievement' },
+  { label: 'Memories', href: '#memories' },
+  { label: 'Final', href: '#final' },
+];
+
+const pageLinks = [
+  { label: 'Gift', href: '/gift' },
+  { label: 'One More Thing', href: '/one-more-thing' },
+];
+
+export function Nav() {
+  const [mobileOpen, setMobileOpen] = useState(false);
+  const [activeSection, setActiveSection] = useState('top');
+
+  useEffect(() => {
+    const sectionIds = sectionLinks.map((l) => l.href.replace('#', ''));
+    const elements = sectionIds
+      .map((id) => document.getElementById(id))
+      .filter(Boolean) as HTMLElement[];
+
+    if (!elements.length) return;
+
+    const observer = new IntersectionObserver(
