+'use client';
+
+import { useEffect, useRef, useState } from 'react';
+
+export function SectionGift() {
+  const sectionRef = useRef<HTMLElement>(null);
+  const [phase, setPhase] = useState<'idle' | 'counting' | 'reveal'>('idle');
+  const [countNum, setCountNum] = useState(3);
+  const [countVisible, setCountVisible] = useState(false);
+  const [revealVisible, setRevealVisible] = useState(false);
+  const triggered = useRef(false);
+
+  useEffect(() => {
+    const section = sectionRef.current;
+    if (!section) return;
+
+    const observer = new IntersectionObserver(
+      ([entry]) => {
+        if (entry.isIntersecting && !triggered.current) {
+          triggered.current = true;
+          startCountdown();
+        }
+      },
+      { threshold: 0.4 }
+    );
+
+    observer.observe(section);
+    return () => observer.disconnect();
+  }, []);
+
+  const startCountdown = () => {
+    setPhase('counting');
+    const numbers = [3, 2, 1];
+    let i = 0;
+
+    const showNext = () => {
+      if (i >= numbers.length) {
+        setCountVisible(false);
+        setTimeout(() => {
+          setPhase('reveal');
+          setTimeout(() => setRevealVisible(true), 200);
+        }, 600);
+        return;
+      }
+
+      setCountNum(numbers[i]);
+      setCountVisible(true);
+
+      setTimeout(() => {
+        setCountVisible(false);
+        i++;
+        setTimeout(showNext, 500);
+      }, 1200);
+    };
+
+    showNext();
+  };
+
+  return (
+    <section className="section-gift" id="gift" ref={sectionRef}>
+      {/* Countdown overlay */}
+      <div className={`section-gift__countdown ${phase === 'counting' ? 'section-gift__countdown--active' : ''}`}>
+        <div className={`section-gift__number ${countVisible ? 'section-gift__number--visible' : 'section-gift__number--exit'}`}>
+          {countNum}
+        </div>
+      </div>
+
+      {/* Reveal */}
+      <div className={`section-gift__reveal ${revealVisible ? 'section-gift__reveal--visible' : ''}`}>
+        <div className="section-gift__reveal-image">
+          <div className="img-slot img-slot--landscape img-slot--warm-deep" />
+        </div>
+        <div className="section-gift__reveal-text">
+          <p className="section-gift__reveal-line">
+            Danish. Faiyza. Hasan.
+          </p>
+        </div>
+      </div>
+
+      {/* Trigger button (visible before countdown) */}
+      {phase === 'idle' && (
+        <button className="section-gift__trigger" onClick={startCountdown}>
+          <span>A gift for you</span>
+        </button>
+      )}
+    </section>
+  );
+}

