+'use client';
+
+import { useState } from 'react';
+
+type AspectRatio = 'portrait' | 'landscape' | 'square';
+type Tone = 'warm' | 'cool' | 'warm-deep' | 'dark';
+
+interface SlotImageProps {
+  src: string;
+  alt?: string;
+  aspect?: AspectRatio;
+  tone?: Tone;
+  className?: string;
+}
+
+export function SlotImage({
+  src,
+  alt = '',
+  aspect = 'landscape',
+  tone = 'warm',
+  className = '',
+}: SlotImageProps) {
+  const [imgError, setImgError] = useState(false);
+
+  if (imgError) {
+    return (
+      <div className={`slot-fallback slot-fallback--${aspect} slot-fallback--${tone} ${className}`} />
+    );
+  }
+
+  return (
+    <img
+      src={src}
+      alt={alt}
+      className={`slot-img ${className}`}
+      onError={() => setImgError(true)}
+      loading="lazy"
+    />
+  );
+}

