+  .section-gallery__item:nth-child(1) { grid-column: 1 / 4; grid-row: span 4; }
+  .section-gallery__item:nth-child(2) { grid-column: 4 / 7; grid-row: span 3; }
+  .section-gallery__item:nth-child(3) { grid-column: 1 / 4; grid-row: span 3; }
+  .section-gallery__item:nth-child(4) { grid-column: 4 / 7; grid-row: span 4; }
+  .section-gallery__item:nth-child(5) { grid-column: 1 / 4; grid-row: span 3; }
