+            <p className="font-body text-white/30 text-sm tracking-luxury uppercase mb-6">
+              Click to open
+            </p>
+            <div className="flex items-center gap-2 text-pink-400/60">
+              <div className="w-6 h-px bg-pink-500/40" />
+              <span className="text-xs font-body tracking-wide">{from}</span>
+              <div className="w-6 h-px bg-pink-500/40" />
+            </div>
+          </div>
+
+          {/* Hover overlay */}
+          <div
+            className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300"
+            style={{
+              background:
+                "radial-gradient(circle at 50% 50%, rgba(255, 61, 107, 0.05), transparent)",
+            }}
+          />
+        </div>
+      ) : (
+        /* Letter opened */
+        <div
+          className="rounded-2xl glass-pink border border-pink-500/20 overflow-hidden"
+          style={{
+            background:
+              "linear-gradient(135deg, rgba(196, 30, 58, 0.05) 0%, rgba(5, 5, 5, 0.9) 100%)",
+            animation: "fadeUp 0.6s ease forwards",
+          }}
+        >
+          {/* Letter header */}
+          <div className="border-b border-pink-500/10 px-8 py-5 flex items-center justify-between">
+            <div className="flex items-center gap-3">
