+import { useCallback, useEffect, useState } from "react";
+import { Header } from "./components/Header";
+import { MessageList } from "./components/MessageList";
+import { ChatInput } from "./components/ChatInput";
+import { Sidebar } from "./components/Sidebar";
+import {
+  sendMessage,
+  getConversations,
+  getConversationDetails,
+} from "./api/chat";
+import type { ChatMessage, Conversation } from "./types";
+
+type ConnectionState = "checking" | "online" | "offline";
+
+function makeId() {
+  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
+}
+
+export default function App() {
+  const [messages, setMessages] = useState<ChatMessage[]>([]);
+  const [draft, setDraft] = useState("");
+  const [isGenerating, setIsGenerating] = useState(false);
+  const [connectionState, setConnectionState] =
+    useState<ConnectionState>("checking");
+  const [errorBanner, setErrorBanner] = useState<string | null>(null);
+
+  // New v0.3 State
+  const [conversations, setConversations] = useState<Conversation[]>([]);
+  const [activeConversationId, setActiveConversationId] = useState<
+    string | null
+  >(null);
+
+  const loadConversations = useCallback(async () => {
+    try {
+      const convs = await getConversations();
+      setConversations(convs);
+    } catch (err) {
+      console.error("Failed to load conversations", err);
+    }
+  }, []);
+
+  useEffect(() => {
+    loadConversations();
+  }, [loadConversations]);
+
+  async function handleSelectConversation(id: string) {
+    if (isGenerating) return;
+    setActiveConversationId(id);
+    try {
+      const details = await getConversationDetails(id);
+      setMessages(details.messages);
+    } catch (err) {
+      setErrorBanner("Failed to load conversation history.");
+    }
+  }
+
+  function handleNewChat() {
+    if (isGenerating) return;
+    setActiveConversationId(null);
+    setMessages([]);
+  }
+
+  async function handleSubmit() {
+    const trimmed = draft.trim();
+    if (!trimmed || isGenerating) return;
+
+    const userMessage: ChatMessage = {
+      id: makeId(),
+      role: "user",
+      content: trimmed,
+    };
+    setMessages((prev) => [...prev, userMessage]);
+    setDraft("");
+    setIsGenerating(true);
+    setErrorBanner(null);
+
+    try {
+      const result = await sendMessage(
+        trimmed,
+        activeConversationId ?? undefined,
+      );
+
+      const assistantMessage: ChatMessage = {
+        id: makeId(),
+        role: "assistant",
+        content: result.content,
+      };
+      setMessages((prev) => [...prev, assistantMessage]);
+      setConnectionState("online");
+
+      // If it was a new chat, update the state with the new ID/Title
+      if (!activeConversationId) {
+        setActiveConversationId(result.conversation_id);
+        setConversations((prev) => [
+          {
+            id: result.conversation_id,
+            title: result.conversation_title,
+            created_at: new Date().toISOString(),
+          },
+          ...prev,
+        ]);
+      }
+    } catch (err) {
+      const detail =
+        err instanceof Error ? err.message : "Something went wrong.";
+      setErrorBanner(detail);
+      setConnectionState("offline");
+    } finally {
+      setIsGenerating(false);
+    }
+  }
+
+  return (
+    <div className="app">
+      <Sidebar
+        conversations={conversations}
+        activeId={activeConversationId}
+        onSelect={handleSelectConversation}
+        onNewChat={handleNewChat}
+      />
+
+      <div className="app__chat-container">
+        <Header
+          connectionState={connectionState}
+          modelName="qwen2.5-coder:7b" // Static for now, will be dynamic in v0.4
+          isGenerating={isGenerating}
+        />
+
+        <main className="app__main">
+          <MessageList messages={messages} isGenerating={isGenerating} />
+        </main>
+
+        {errorBanner && (
+          <div className="error-banner" role="alert">
+            {errorBanner}
+          </div>
+        )}
+
+        <footer className="app__footer">
+          <ChatInput
+            value={draft}
+            onChange={setDraft}
+            onSubmit={handleSubmit}
+            disabled={isGenerating}
+          />
+          <p className="app__hint">
+            Enter to send · Shift + Enter for a new line
+          </p>
+        </footer>
+      </div>
+    </div>
+  );
+}

