+import { useEffect, useRef } from "react";
+import type { ChatMessage } from "../types";
+import { MessageBubble } from "./MessageBubble";
+import { TypingIndicator } from "./TypingIndicator";
+
+interface MessageListProps {
+  messages: ChatMessage[];
+  isGenerating: boolean;
+}
+
+export function MessageList({ messages, isGenerating }: MessageListProps) {
+  const endRef = useRef<HTMLDivElement>(null);
+
+  useEffect(() => {
+    endRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
+  }, [messages, isGenerating]);
+
+  if (messages.length === 0) {
+    return (
+      <div className="empty-state">
+        <div className="empty-state__ring" aria-hidden="true" />
+        <p className="empty-state__title">Systems nominal.</p>
+        <p className="empty-state__subtitle">
+          Send a message to start talking with your local model.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="message-list">
+      {messages.map((message) => (
+        <MessageBubble key={message.id} message={message} />
+      ))}
+      {isGenerating && <TypingIndicator />}
+      <div ref={endRef} />
+    </div>
+  );
+}

