- * Tic Tac Toe Game Logic
- *
- * Architecture:
- * - Board is represented as a 1D array of 9 elements.
- * - Indices 0-2: Top row, 3-5: Middle row, 6-8: Bottom row.
- * - 'X' is represented by 1, 'O' by -1, Empty by 0.
- */
-
-// Global Game State
-let board = [];
-let currentPlayer = "X";
-let isGameActive = false;
-
-// DOM Elements
-const boardElement = document.getElementById("board");
-const statusElement = document.getElementById("status");
-const restartBtn = document.getElementById("restartBtn");
-
-// Winning Combinations (Indices)
-const winningCombinations = [
-  [0, 1, 2], // Top row
-  [3, 4, 5], // Middle row
-  [6, 7, 8], // Bottom row
-  [0, 3, 6], // Left column
-  [1, 4, 7], // Middle column
-  [2, 5, 8], // Right column
-  [0, 4, 8], // Diagonal top-left to bottom-right
-  [2, 4, 6], // Diagonal top-right to bottom-left
-];
-
-/**
- * Initializes the game board array and renders the UI.
- */
-function initializeGame() {
-  // Set up the 1D array representation (0 = empty)
-  board = Array(9).fill("");
-
-  // X always starts first
-  currentPlayer = "X";
-  isGameActive = true;
-
-  // Clear the DOM board
-  boardElement.innerHTML = "";
-
-  // Create 9 cell elements
-  for (let i = 0; i < 9; i++) {
-    const cellElement = document.createElement("button");
-    cellElement.classList.add("cell");
-    cellElement.setAttribute("data-index", i);
-
-    // Attach event listener for clicks
-    cellElement.addEventListener("click", handleCellClick);
-
-    boardElement.appendChild(cellElement);
-  }
-
-  updateStatus();
-}
-
-/**
- * Handles a click on a specific cell.
- * @param {Event} event - The click event object.
- */
-function handleCellClick(event) {
-  const cell = event.target;
-  const index = parseInt(cell.getAttribute("data-index"));
-
-  // Ignore click if cell is already filled or game is over
-  if (board[index] !== "" || !isGameActive) {
-    return;
-  }
-
-  // Update board state and UI
-  board[index] = currentPlayer;
-  cell.textContent = currentPlayer;
-  cell.disabled = true;
-
-  // Check for win or draw after every move
-  const winningCombo = checkWinner();
-  if (winningCombo) {
-    handleGameWin(winningCombo);
-  } else if (checkDraw()) {
-    handleGameDraw();
-  } else {
-    switchPlayer();
-  }
-}
-
-/**
- * Switches the current player from X to O, or O to X.
- */
-function switchPlayer() {
-  currentPlayer = currentPlayer === "X" ? "O" : "X";
-  updateStatus();
-}
-
-/**
- * Checks if the current player has won.
- * @returns {Array|null} The winning combination array if won, otherwise null.
- */
-function checkWinner() {
-  for (let i = 0; i < winningCombinations.length; i++) {
-    const [a, b, c] = winningCombinations[i];
-
-    // Check if all three indices have the current player's mark
-    if (
-      board[a] === currentPlayer &&
-      board[b] === currentPlayer &&
-      board[c] === currentPlayer
-    ) {
-      return winningCombinations[i]; // Return the winning combination
-    }
-  }
-  return null;
-}
-
-/**
- * Checks if the game is a draw (all cells filled, no winner).
- * @returns {boolean} True if draw, false otherwise.
- */
-function checkDraw() {
-  // If no empty strings ('') are found, the board is full
-  return !board.includes("");
-}
-
-/**
- * Handles the logic when a player wins.
- * @param {Array} winningCombo - The indices of the winning cells.
- */
-function handleGameWin(winningCombo) {
-  isGameActive = false;
-
-  // Highlight winning cells
-  winningCombo.forEach((index) => {
-    const cell = boardElement.children[index];
-    cell.classList.add("win");
-  });
-
-  statusElement.textContent = `Player ${currentPlayer} wins!`;
-}
-
-/**
- * Handles the logic when the game ends in a draw.
- */
-function handleGameDraw() {
