+            Cancel
+          </button>
+          <button
+            onClick={onConfirm}
+            className="px-4 py-2 text-[var(--heading)] rounded-lg font-medium transition-colors"
+            style={{ background: tk.danger }}
+          >
+            Delete
+          </button>
+        </div>
+      </div>
+    </div>
+  );
+}

