+interface RichTextEditorProps {
+  content: string;
+  onChange: (html: string) => void;
+  onFileUpload?: (file: File) => Promise<string>; // Returns S3 URL
+}
+
+export default function RichTextEditor({
+  content,
+  onChange,
+  onFileUpload,
+}: RichTextEditorProps) {
+  const [showPlusMenu, setShowPlusMenu] = useState(false);
+  const [isTableActive, setIsTableActive] = useState(false);
+
+  const insertChecklist = () => {
+    if (!editor) return;
+    editor.chain().focus().toggleTaskList().run();
+    setShowPlusMenu(false);
+  };
+
+  const insertImage = async () => {
+    if (!editor) return;
+    const input = document.createElement("input");
+    input.type = "file";
+    input.accept = "image/*";
+
+    input.onchange = async () => {
+      const file = input.files?.[0];
+      if (!file) return;
+
+      let imageUrl = URL.createObjectURL(file); // Fallback optimistic preview
+
+      if (onFileUpload) {
+        try {
+          imageUrl = await onFileUpload(file); // Wait for real S3 URL
+        } catch (err) {
+          console.error("Image upload failed", err);
+          alert("Image upload failed. Using local preview.");
+        }
+      }
+
+      editor
+        .chain()
+        .focus()
+        .insertContent({
+          type: "image",
+          attrs: {
+            src: imageUrl,
+            alt: file.name,
+            title: file.name,
+          },
+        })
+        .run();
+      setShowPlusMenu(false);
+    };
+    input.click();
+  };
+
+  const insertFile = async () => {
+    const input = document.createElement("input");
+    input.type = "file";
+    input.multiple = true;
+
+    input.onchange = async () => {
+      const files = input.files;
+      if (!files || !editor) return;
+
+      const formatSize = (bytes: number) => {
+        if (bytes < 1024) return `${bytes} B`;
+        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
+        return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
+      };
+
+      for (const file of Array.from(files)) {
+        let fileUrl = URL.createObjectURL(file);
+
+        if (onFileUpload) {
+          try {
+            fileUrl = await onFileUpload(file);
+          } catch (err) {
+            console.error("File upload failed", err);
+            alert("File upload failed. Using local preview.");
+          }
+        }
+
+        editor
+          .chain()
+          .focus()
+          .insertContent({
+            type: "fileAttachment",
+            attrs: {
+              filename: file.name,
+              size: formatSize(file.size),
+              url: fileUrl,
+              mimeType: file.type,
